package com.travelbird.ai.service;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
import com.travelbird.ai.dto.internal.*;import com.travelbird.ai.entity.*;import com.travelbird.ai.repository.*;import com.travelbird.global.error.*;import com.travelbird.place.repository.PlaceRepository;import com.travelbird.trip.entity.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class AiCallbackValidationFailureTest {@Test void unknownPlaceReturnsInvalidResponseAndCommitsFailedState(){var now=LocalDateTime.of(2026,9,12,12,0);var job=AiRecommendationJob.queued(7L,null,null,AiRequestType.GENERAL,"11110",LocalDate.of(2026,10,1),LocalDate.of(2026,10,1),CompanionType.SOLO,Pace.NORMAL,"[]","[]","[]","[]",true,now);job.start(now);var jobs=mock(AiRecommendationJobRepository.class);when(jobs.findByIdForUpdate(7L)).thenReturn(Optional.of(job));var snapshots=mock(RecommendationSnapshotCodec.class);when(snapshots.read(job)).thenReturn(new RecommendationJobRequest(7L,AiRequestType.GENERAL,"11110",LocalDate.of(2026,10,1),LocalDate.of(2026,10,1),CompanionType.SOLO,List.of(),Pace.NORMAL,List.of(),List.of(),List.of(),true));var places=mock(PlaceRepository.class);when(places.findAllById(any())).thenReturn(List.of());var service=new AiCallbackService(jobs,mock(AiTripPreviewRepository.class),mock(AiPreviewPersistenceService.class),mock(AiJobTransitionService.class),new AiPreviewRouteValidator(),snapshots,places,Clock.fixed(now.toInstant(ZoneOffset.UTC),ZoneOffset.UTC));var request=new AiCallbackRequest(7L,"COMPLETED","제목","설명",List.of(new AiResultDay(1,List.of(new AiResultPlace(99L,1,"충분히 구체적인 추천 이유 문장입니다.")))),null,null,null,null,null,null);assertThatThrownBy(()->service.handle(request)).isInstanceOf(AiResultValidationException.class).extracting("errorCode").isEqualTo(ErrorCode.INVALID_AI_RESPONSE);assertThat(job.getStatus()).isEqualTo(BackendAiJobStatus.FAILED);assertThat(job.getErrorCode()).isEqualTo(AiJobFailureCode.AI_PLACE_NOT_FOUND.name());}}
